scriptTask.script:
if (!execution.hasVariable('plazoRespuesta')) {
  execution.setVariable('plazoRespuesta', 'P5D')
}
execution.setVariable('recordatorios', 0)
println "Propuesta enviada a la empresa"

def n = (execution.getVariable('recordatorios') ?: 0) + 1
execution.setVariable('recordatorios', n)
if (n <= 2) {
  println "Recordatorio ${n} enviado"
}
